state=dict(status='prepared',pid=os.getpid(),directory=str(out),role='Local Restorer',system=system,prompt=prompt,guided=True,coordinator_supplied_algorithm_plan=True,native_Chat=False,new_training=False,source_accepted=False)
def save():
 (out/'protocol.json').write_text(json.dumps(state,indent=2)+'\n');(ROOT/'verification/local-native-math-optimization-current.json').write_text(json.dumps(state,indent=2)+'\n')
